import sys
from collections import defaultdict

def main():
    lines = [line.strip() for line in sys.stdin if line.strip()]
    N = int(lines[0])
    categories = {}
    for i in range(1, N+1):
        parts = lines[i].split()
        name = parts[0]
        W = int(parts[1])
        words = parts[2:2+W]
        categories[name] = words

    statement_words = []
    for line in lines[N+1:]:
        statement_words.extend(line.split())

    word_counts = defaultdict(int)
    for word in statement_words:
        word_counts[word] += 1

    max_score = -1
    best_categories = []

    for name, words in categories.items():
        score = 0
        for word in words:
            score += word_counts.get(word, 0)
        if score > max_score:
            max_score = score
            best_categories = [name]
        elif score == max_score:
            best_categories.append(name)

    for category in sorted(best_categories):
        print(category)

if __name__ == "__main__":
    main()

